  api.box({w:3.2, h:0.2, d:0.5, pos:[0,0.1,5.25], color:C_DARK_WOOD});
  api.box({w:3.1, h:0.2, d:0.5, pos:[0,0.3,4.75], color:C_DARK_WOOD});

